function printContentHtml(contentHtml)
{
    var mywindow = window.open('', 'PRINT', 'height=600,width=956');

    mywindow.document.write('<html><head><title></title>');
    mywindow.document.write('</head><body>');
    mywindow.document.write(contentHtml);
    mywindow.document.write('</body></html>');

    mywindow.document.close(); // necessary for IE >= 10
    mywindow.focus(); // necessary for IE >= 10*/

    var isChrome = Boolean(mywindow.chrome);
    if (isChrome) {
        mywindow.print();
        setTimeout(function () {
            mywindow.close();
        }, 1);
    }
    else {
        mywindow.print();
        mywindow.close();
    }

    return true;
}
function EnetProductComment(){
    var me  = this;
    var ACCESS_TOKEN = null;
    this.initialize = function($container,_access_token) {
        ACCESS_TOKEN = _access_token;
        $container.append(getProductCommentsContainerTemp);
    };
    this.isAuthenticated = function() {
        return (ACCESS_TOKEN != null && ACCESS_TOKEN.length > 0);
    };
    this.loadProductComroom = function(productcode) {
        $.ajax({
            url: '/api/v0/community/'+productcode+'/get-product-comroom.json',
            type: 'GET',
            contentType: "application/json",
            success: function(result) {
                if (result.comroomid != null && result.title.length > 0) {
                    $('.current-article .comroom-comments').html('');
                    processLoadedCommroom(result.code);
                }
            }
        });
    };
    function processLoadedCommroom(code) {
        if (code != null) {
            $('.one-middle-content').removeClass('active');
            $.ajax({
                url: '/api/v0/community/'+code+'/comments.json',
                type: 'GET',
                contentType: "application/json",
                success: function(result) {
                    if (result.count != null && result.count > 0) {
                        for (var i=result.comments.length; i>0;i--) {
                            var cItemi = result.comments[i-1];
                            appendCommentItem(cItemi);
                        }
                        $('.comroom-comments').removeClass('d-none');
                    } else {
                        $('.comroom-comments').addClass('d-none');
                    }
                    if (me.isAuthenticated()) {
                        $('#post-comment-form').addClass('show');
                        $('#post-comment-form').attr('targetcode',code);
                        $('#post-comment-form').attr('rate',5);
                        $('#post-comment-form').find('.btn-post-comment').on('click',function(){
                            sendComment();
                        });
                        $("#post-comment-form .form-comment-msg").keyup(function(event) {
                            if (event.keyCode === 13) {
                                sendComment();
                            }
                        });
                        //rate
                        $('#form-comment-rate').starrr({
                            rating: 5
                        })
                        $('#form-comment-rate').on('starrr:change', function(e, value) {
                            $('#post-comment-form').attr('rate',value);
                        });
                    }
                }
            });
            $('.current-article.one-middle-content').addClass('active');
        }
    }
    function sendComment() {
        var rate = $('#post-comment-form').attr('rate');
        var code = $('#post-comment-form').attr('targetcode');
        var msg = $('#post-comment-form .form-comment-msg').val();
        if (msg.length < 2) {
            $('#post-comment-form .form-comment-msg').focus();
            return;
        } else {
            postComment(code,msg,rate);
            $('#post-comment-form .form-comment-msg').val('');
        }
    }
    function getCommentMsgTemp() {
        var contentHTML = [];
        contentHTML.push('<div class="d-flex msg-container" commentid="{commentid}">');
        contentHTML.push(' <div class="me-3">');
        contentHTML.push('  <div class="avatar avatar-sm rounded-circle">');
        contentHTML.push('    <img src="{avatarimg}" alt="...">');
        contentHTML.push('  </div>');
        contentHTML.push(' </div>');
        contentHTML.push(' <div class="msg_container-content">');
        contentHTML.push('    <div class="d-flex align-items-center align-self-center">');
        contentHTML.push('      <span class="d-block lh-none text-sm font-semibold text-heading">{authorname}</span>');
        contentHTML.push('      <span class="d-block lh-none mx-3 text-xs text-muted">{ago}</span>');
        contentHTML.push('      <span class="d-block lh-none mx-3 text-xs text-muted">{rate}</span>');
        contentHTML.push('    </div>');
        contentHTML.push('    <div class="d-flex mt-2">');
        contentHTML.push('     <div class="px-3 py-3 rounded-bottom-3 rounded-top-end-3 text-sm bg-gray-100">{msg}</div>');
        contentHTML.push('    </div>');
        contentHTML.push(' </div>');
        contentHTML.push('</div>');
        return contentHTML.join("")
    }
    function postComment(code,msg,rate) {
        var commentItem = {};
        commentItem.msg = msg;
        commentItem.rate = rate;
        $.ajax({
            url: '/api/v0/community/'+code+'/post-comment.json',
            type: 'POST',
            contentType: "application/json",
            data: JSON.stringify(commentItem),
            dataType: "json",
            beforeSend: function(xhr) {
                xhr.setRequestHeader("Authorization", "Bearer " + ACCESS_TOKEN);
            },
            success: function(result) {
                if (result.commentid != null) {
                    appendCommentItem(result);
                }
            }
        });
    }
    function appendCommentItem(cItem) {
        var msgContent = getCommentMsgTemp().replace('{authorname}',cItem.authorname).replace('{commentid}',cItem.commentid);
        msgContent = msgContent.replace('{ago}',cItem.ago).replace('{msg}',cItem.msg);
        if (cItem.rate) {
            var rateHtml = ''
            for(var i = 0; i < cItem.rate; i++){
                rateHtml += '<i class="bi bi-star-fill"></i>';
            }
            msgContent = msgContent.replace('{rate}',rateHtml);
        } else {
            msgContent = msgContent.replace('{rate}','');
        }
        //TODO
        msgContent = msgContent.replace('{avatarimg}','/themes/grayscale/assets/img/avatar/avatar-1.png');
        $('.current-article .comroom-comments').append(msgContent);
    }
    function getComroomsTemp(comroomResp) {
        var contentHTML = [];
        contentHTML.push('<div class="vstack h-full">');
        contentHTML.push('  <div class="position-sticky top-0">');
        contentHTML.push('    <div class="d-flex justify-content-between">');
        contentHTML.push('      <div><h5><i class="bi bi-globe me-3"></i> Discussion</h5></div>');
        if (me.isAuthenticated()) {
            contentHTML.push('      <div class="pb-3"><a href="#" data-bs-toggle="modal" data-bs-target="#create_comroom_modal" class="btn-create-comroom"><i class="bi bi-plus-circle-dotted"></i> </a></div>');
        }
        contentHTML.push('     </div>');
        contentHTML.push('   </div>');
        contentHTML.push(' <div class="flex-fill px-3 py-5 p-lg-7 overflow-y-lg-auto">');
        contentHTML.push('    <div class="list-group list-group-flush comroom-items">');

        for(var i=0;i<comroomResp.items.length;i++) {
            var ri = comroomResp.items[i];
            contentHTML.push('  <div class="list-group-item p-1 comroom-item">');
            contentHTML.push('    <a class="mb-0 small text-muted comroom-item-link" comroomid="'+ri.comroomid+'" href="#">'+ri.title+'</a>');
            contentHTML.push('  </div>');
        }

        contentHTML.push('    </div>');
        contentHTML.push(' </div>');
        contentHTML.push('</div>');
        return contentHTML.join("")
    }
    function getProductCommentsContainerTemp() {
        var contentHTML = [];
        contentHTML.push('<div class="container">');
        contentHTML.push(' <article class="article current-article one-middle-content active">');
        contentHTML.push('    <div class="comroom-comments flex-fill px-3 py-5 p-lg-7 overflow-y-lg-auto">');
        contentHTML.push('    </div>');
        contentHTML.push('    <div id="post-comment-form" class="post-comment-form position-sticky bottom-0 flex-auto p-3 px-lg-7 py-lg-5 overlap-10" targetcode="">');
        contentHTML.push('      <div class="d-flex"><label>Đánh giá: </label><div id="form-comment-rate" class="ms-2 starrr"></div></div>');
        contentHTML.push('      <div class="d-flex align-items-center bg-surface-primary border px-5 rounded-pill">');
        contentHTML.push('        <div class="flex-fill d-flex align-items-center">');
        contentHTML.push('          <div class="hstack gap-3 align-items-center w-full">');
        contentHTML.push('            <div></div>');
        contentHTML.push('            <div class="card-comment-box">');
        contentHTML.push('               <input class="form-control py-4 form-comment-msg" name="form-comment-msg" placeholder="Add a comment...">');
        contentHTML.push('            </div>');
        contentHTML.push('          </div>');
        contentHTML.push('        </div>');
        contentHTML.push('        <div class="flex-auto text-end">');
        contentHTML.push('          <div class="hstack gap-3 align-items-center">');
        contentHTML.push('            <a href="#!" class="text-lg text-muted btn-post-comment"><i class="bi bi-send"></i></a>');
        contentHTML.push('          </div>');
        contentHTML.push('        </div>');
        contentHTML.push('      </div>');
        contentHTML.push('    </div>');
        contentHTML.push(' </div>');
        contentHTML.push('</div>');
        return contentHTML.join("")
    }
}
var ENET_PRODUCT_COMMENT = new EnetProductComment();

function EnetClockDownComponent() {
    var me = this;
    me.getTimeRemaining = function(endtime) {
        const total = Date.parse(endtime) - Date.parse(new Date());
        const seconds = Math.floor((total / 1000) % 60);
        const minutes = Math.floor((total / 1000 / 60) % 60);
        const hours = Math.floor((total / (1000 * 60 * 60)) % 24);
        const days = Math.floor(total / (1000 * 60 * 60 * 24));

        return {
            total,
            days,
            hours,
            minutes,
            seconds
        };
    }

    me.initializeClock = function (id, endtime) {
        const clock = document.getElementById(id);
        const daysSpan = clock.querySelector('.days');
        const hoursSpan = clock.querySelector('.hours');
        const minutesSpan = clock.querySelector('.minutes');
        const secondsSpan = clock.querySelector('.seconds');

        function updateClock() {
            const t = me.getTimeRemaining(endtime);

            //daysSpan.innerHTML = t.days;
            hoursSpan.innerHTML = ('0' + t.hours).slice(-2);
            minutesSpan.innerHTML = ('0' + t.minutes).slice(-2);
            secondsSpan.innerHTML = ('0' + t.seconds).slice(-2);

            if (t.total <= 0) {
                clearInterval(timeinterval);
            }
        }

        updateClock();
        const timeinterval = setInterval(updateClock, 1000);
    }
}
var ENET_CLOCKDOWN_COMPONENT = new EnetClockDownComponent();

$(document).ready(function () {
    if ($("#productSlider").length) {
        $("#productSlider").lightSlider({
            gallery: true,
            item: 1,
            loop: true,
            slideMargin: 0,
            thumbItem: 6
        });
    }
    $('.plus-btn').click(function () {
        var rateid = $(this).attr('id').split('_')[1];
        var max = parseInt($('.quantity-' + rateid).attr('max'));
        var qty = parseInt($('.quantity-' + rateid).val());
        if (qty < max) {
            qty++;
            $('.quantity-' + rateid).val(qty);
        }
    });
    $('.minus-btn').click(function () {
        var rateid = $(this).attr('id').split('_')[1];
        var min = parseInt($('.quantity-' + rateid).attr('min'));
        var qty = parseInt($('.quantity-' + rateid).val());
        if (qty > min) {
            qty--;
            $('.quantity-' + rateid).val(qty);
        }
    });
    $('input[name="quantity"]').on('change', function () {
        var max = $(this).attr('max');
        var min = $(this).attr('min');
        var qty = $(this).val();
        if (isNaN(qty)) {
            qty = 0;
        }
        if (qty > max) {
            qty = max;
            $(this).val(qty);
        }
        if (qty < min) {
            qty = min;
            $(this).val(qty);
        }
    });
    $('.btn-print-one-product-quotation').on('click',function(){
        var productcode = $(this).data('productcode');
        var productpriceid = $(this).data('productpriceid');
        $.ajax({
            url: '/ajax/custom/'+productcode+'/'+productpriceid+'/one-product-quotation.json',
            type: "GET",
            contentType: "application/json",
            success: function (result) {
                if (result.emailContent != '') {
                    printContentHtml(result.emailContent);
                }
            }
        });
    });
    if($('.show-comments-for-productcode').length) {
        var $commentcontainer = $('.slice.product-info');
        if ($commentcontainer.length) {
            var _access_token = $('.user_access_token').length ? $('.user_access_token').html() : '';
            ENET_PRODUCT_COMMENT.initialize($commentcontainer,_access_token);
            var pcode = $('.show-comments-for-productcode').html();
            ENET_PRODUCT_COMMENT.loadProductComroom(pcode);
        }
    }
    if ($('#enet-clockdown').length) {
        const deadlineSecond = $('#enet-clockdown').data('deadline') || (30 * 60 * 1000); //30p = 30 * 60 * 1000
        const deadline = new Date(Date.parse(new Date()) +  deadlineSecond);
        ENET_CLOCKDOWN_COMPONENT.initializeClock('enet-clockdown', deadline);
    }
    if ($('.feature-container').length) {
        $('.feature-container').each(function () {
            var productcode = $(this).data('code') || $('#productCode').html();
            var ajaxurl = '/ajax/custom/' + productcode + "/features.html";
            $(this).load(ajaxurl, function(response, status, xhr) {});
        });
    }
});
